INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('pork-vindaloo', 'Pork Vindaloo', 'पोर्क विंदालू', 'पोर्क विंदालू', 'goan', false, '{"lunch","dinner"}', 30, 60, 'medium', 2, 'steamed-rice', 480, 32, 12, 34, 2, 'A fiery Goan curry of pork marinated in vinegar, red chillies, and warm spices — a Portuguese-influenced classic.', 'सिरके, लाल मिर्च और गरम मसालों में मैरिनेट किया हुआ पोर्क का तीखा गोवन करी — पुर्तगाली प्रभाव वाला क्लासिक व्यंजन।', 'व्हिनेगर, लाल मिरच्या आणि गरम मसाल्यांमध्ये मॅरिनेट केलेल्या डुकराच्या मांसाची तिखट गोवन करी — पोर्तुगीज प्रभावाचा पारंपरिक पदार्थ.', 'https://www.youtube.com/results?search_query=pork+vindaloo+recipe+goan+style+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('chicken-xacuti', 'Chicken Xacuti', 'चिकन शाकुती', 'चिकन शाकुती', 'goan', false, '{"lunch","dinner"}', 25, 45, 'hard', 2, 'steamed-rice', 420, 30, 10, 30, 3, 'A complex Goan curry with chicken simmered in a rich coconut and roasted spice gravy with poppy seeds and star anise.', 'भुने मसालों, नारियल, खसखस और चक्र फूल से बनी समृद्ध ग्रेवी में पका चिकन — गोवा का जटिल और स्वादिष्ट व्यंजन।', 'भाजलेल्या मसाल्यांच्या, नारळाच्या, खसखशीच्या आणि बाद्यानच्या रश्शात शिजवलेले चिकन — गोव्याचा गुंतागुंतीचा आणि चविष्ट पदार्थ.', 'https://www.youtube.com/results?search_query=chicken+xacuti+recipe+goan+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('fish-recheado', 'Fish Recheado', 'फिश रेचियाड', 'फिश रेशाद', 'goan', false, '{"lunch","dinner"}', 20, 15, 'medium', 2, 'steamed-rice', 350, 28, 8, 23, 1.5, 'Whole fish stuffed with a spicy red recheado masala paste and shallow-fried until crisp — a Goan celebration staple.', 'तीखे लाल रेचियाड मसाले से भरी पूरी मछली को कम तेल में कुरकुरा तला हुआ — गोवा के त्योहारों का खास व्यंजन।', 'तिखट लाल रेशाद मसाल्याने भरलेली पूर्ण मासळी कुरकुरीत तळलेली — गोव्याच्या सणासुदीचा खास पदार्थ.', 'https://www.youtube.com/results?search_query=fish+recheado+recipe+goan+masala+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('ros-omelette', 'Ros Omelette', 'रॉस ऑमलेट', 'रॉस ऑम्लेट', 'goan', false, '{"breakfast","lunch","dinner"}', 10, 15, 'easy', 2, 'pav', 380, 18, 30, 22, 2, 'Goa''s iconic street food — a fluffy masala omelette smothered in spicy coconut-tomato ros gravy, served with pav.', 'गोवा का मशहूर स्ट्रीट फूड — मसाला ऑमलेट पर तीखी नारियल-टमाटर रॉस ग्रेवी, पाव के साथ।', 'गोव्याचा प्रसिद्ध स्ट्रीट फूड — मसाला ऑम्लेटवर तिखट नारळ-टोमॅटो रॉस ग्रेव्ही, पावासोबत.', 'https://www.youtube.com/results?search_query=ros+omelette+goan+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('prawn-balchao', 'Prawn Balchao', 'प्रॉन बालचाओ', 'कोळंबी बालचाव', 'goan', false, '{"lunch","dinner"}', 20, 25, 'medium', 2, 'steamed-rice', 310, 24, 14, 18, 2, 'A tangy, fiery Goan prawn pickle-curry with vinegar, red chillies, and a hint of sugar — improves with resting.', 'सिरका, लाल मिर्च और चीनी की हल्की मिठास वाला खट्टा-तीखा गोवन झींगा अचार-करी — रखने पर स्वाद और बढ़ता है।', 'व्हिनेगर, लाल मिरच्या आणि साखरेच्या हलक्या गोडव्याची आंबट-तिखट गोवन कोळंबी लोणचे-करी — ठेवल्यावर चव अजून वाढते.', 'https://www.youtube.com/results?search_query=prawn+balchao+goan+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('goan-fish-curry-rice', 'Goan Fish Curry Rice', 'गोवन फिश करी राइस', 'गोवन मासा करी भात', 'goan', false, '{"lunch","dinner"}', 15, 25, 'easy', 2, 'steamed-rice', 390, 26, 18, 24, 3, 'The everyday soul food of Goa — fresh fish simmered in a tangy coconut and kokum gravy, always served with plain rice.', 'गोवा का रोज़ का खाना — ताज़ी मछली नारियल और कोकम की खट्टी ग्रेवी में, हमेशा सादे चावल के साथ।', 'गोव्याचे रोजचे जेवण — ताजी मासळी नारळ आणि कोकमाच्या आंबट रश्शात, नेहमी वरणभातासोबत.', 'https://www.youtube.com/results?search_query=goan+fish+curry+rice+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('sorpotel', 'Sorpotel', 'सोरपोटेल', 'सोरपोटेल', 'goan', false, '{"dinner"}', 30, 90, 'hard', 2, 'pav', 520, 35, 10, 38, 1.5, 'A rich, spicy Goan pork offal stew with liver, cooked in vinegar and toddy — a Christmas and feast-day tradition.', 'पोर्क और कलेजी का गाढ़ा, तीखा गोवन स्टू, सिरके और ताड़ी में पका — क्रिसमस और त्योहारों की परंपरा।', 'डुकराचे मांस आणि काळजी यांचा घट्ट, तिखट गोवन स्ट्यू, व्हिनेगर आणि ताडीत शिजवलेला — नाताळ आणि सणांची परंपरा.', 'https://www.youtube.com/results?search_query=sorpotel+recipe+goan+pork+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('chicken-cafreal', 'Chicken Cafreal', 'चिकन कॅफ्रियल', 'चिकन कॅफ्रिअल', 'goan', false, '{"lunch","dinner"}', 20, 30, 'medium', 2, 'steamed-rice', 390, 32, 6, 26, 2, 'Goan green masala chicken marinated in a vibrant paste of coriander, green chillies, and spices, then pan-fried.', 'हरे धनिये, हरी मिर्च और मसालों के पेस्ट में मैरिनेट करके तवे पर भुना गोवन ग्रीन मसाला चिकन।', 'हिरव्या कोथिंबीर, हिरव्या मिरच्या आणि मसाल्यांच्या पेस्टमध्ये मॅरिनेट करून तव्यावर भाजलेले गोवन ग्रीन मसाला चिकन.', 'https://www.youtube.com/results?search_query=chicken+cafreal+goan+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('ambot-tik', 'Ambot Tik', 'आमबोट टिक', 'आंबोट तिक', 'goan', false, '{"lunch","dinner"}', 15, 25, 'medium', 2, 'steamed-rice', 320, 25, 12, 20, 2, 'A sour and spicy Goan shark or fish curry with kokum and a fiery red masala — the name literally means sour-spicy.', 'कोकम और तीखे लाल मसाले वाली खट्टी-तीखी गोवन मछली करी — नाम का मतलब ही खट्टा-तीखा है।', 'कोकम आणि तिखट लाल मसाल्याची आंबट-तिखट गोवन माशाची करी — नावाचा अर्थच आंबट-तिखट.', 'https://www.youtube.com/results?search_query=ambot+tik+goan+fish+curry+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('sorak', 'Sorak', 'सोरक', 'सोरक', 'goan', true, '{"lunch","dinner"}', 10, 20, 'easy', 2, 'steamed-rice', 180, 3, 14, 13, 3, 'A simple, everyday Goan coconut curry without any vegetables — just coconut, spices, and a light gravy to eat with rice.', 'बिना सब्ज़ी की सादी, रोज़ की गोवन नारियल करी — बस नारियल, मसाले और हल्की ग्रेवी, चावल के साथ।', 'भाजीशिवाय बनणारी साधी, रोजची गोवन नारळाची करी — फक्त नारळ, मसाले आणि पातळ रस्सा, भातासोबत.', 'https://www.youtube.com/results?search_query=sorak+curry+goan+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('khatkhate', 'Khatkhate', 'खटखटे', 'खटखटे', 'goan', true, '{"lunch","dinner"}', 20, 35, 'medium', 2, 'steamed-rice', 240, 8, 32, 10, 7, 'A festive Goan mixed vegetable stew cooked with five or more vegetables, lentils, and fresh coconut — made during Ganesh Chaturthi.', 'पाँच या अधिक सब्ज़ियों, दाल और ताज़े नारियल से बना त्योहारी गोवन मिश्रित सब्ज़ी स्टू — गणेश चतुर्थी में बनता है।', 'पाच किंवा अधिक भाज्या, डाळ आणि ताज्या नारळाने बनवलेला सणासुदीचा गोवन मिश्र भाजी स्ट्यू — गणेश चतुर्थीला बनतो.', 'https://www.youtube.com/results?search_query=khatkhate+goan+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('mushroom-xacuti', 'Mushroom Xacuti', 'मशरूम शाकुती', 'मशरूम शाकुती', 'goan', true, '{"lunch","dinner"}', 20, 30, 'medium', 2, 'steamed-rice', 280, 8, 16, 21, 4, 'A vegetarian take on the classic xacuti — mushrooms simmered in a rich roasted spice and coconut gravy.', 'क्लासिक शाकुती का शाकाहारी संस्करण — भुने मसालों और नारियल की गाढ़ी ग्रेवी में पके मशरूम।', 'पारंपरिक शाकुतीचा शाकाहारी पर्याय — भाजलेल्या मसाल्यांच्या आणि नारळाच्या घट्ट रश्शात शिजवलेले मशरूम.', 'https://www.youtube.com/results?search_query=mushroom+xacuti+recipe+goan+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('veg-xacuti', 'Veg Xacuti', 'वेज शाकुती', 'वेज शाकुती', 'goan', true, '{"lunch","dinner"}', 25, 35, 'medium', 2, 'steamed-rice', 300, 7, 22, 21, 5, 'Mixed vegetables like potato, carrot, and beans in a roasted spice and coconut xacuti gravy — a hearty vegetarian Goan dish.', 'आलू, गाजर और बीन्स जैसी मिली-जुली सब्ज़ियां भुने मसाले और नारियल की शाकुती ग्रेवी में — पेट भरने वाला शाकाहारी गोवन व्यंजन।', 'बटाटा, गाजर आणि शेवग्याच्या शेंगा अशा मिश्र भाज्या भाजलेल्या मसाल्यांच्या आणि नारळाच्या शाकुती रश्शात — पोटभरीचा शाकाहारी गोवन पदार्थ.', 'https://www.youtube.com/results?search_query=veg+xacuti+recipe+goan+vegetarian+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('solachi-kadhi', 'Solachi Kadhi', 'सोलाची कढ़ी', 'सोलाची कढी', 'goan', true, '{"lunch","dinner"}', 10, 15, 'easy', 2, 'steamed-rice', 160, 3, 10, 12, 2, 'A refreshing Goan kokum and coconut milk curry — light, tangy, and served cold or warm as a digestive with meals.', 'ताज़गी भरी गोवन कोकम और नारियल दूध की कढ़ी — हल्की, खट्टी, ठंडी या गुनगुनी खाने के साथ पाचक के रूप में।', 'ताजेतवाने गोवन कोकम आणि नारळाच्या दुधाची कढी — हलकी, आंबट, थंड किंवा कोमट जेवणासोबत पाचक म्हणून.', 'https://www.youtube.com/results?search_query=sol+kadhi+goan+recipe+coconut+kokum+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('alsande', 'Alsande', 'अलसांदे', 'अळसांदे', 'goan', true, '{"lunch","dinner"}', 15, 35, 'easy', 2, 'steamed-rice', 260, 12, 34, 9, 8, 'A simple Goan black-eyed pea curry cooked in coconut and mild spices — a protein-rich everyday vegetarian dish.', 'नारियल और हल्के मसालों में पकी लोबिया की सादी गोवन करी — प्रोटीन भरपूर रोज़ का शाकाहारी व्यंजन।', 'नारळ आणि सौम्य मसाल्यांत शिजवलेल्या अळसांद्याची साधी गोवन करी — प्रथिनयुक्त रोजचा शाकाहारी पदार्थ.', 'https://www.youtube.com/results?search_query=alsande+curry+goan+recipe+black+eyed+peas+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('patal-bhaji', 'Patal Bhaji', 'पातळ भाजी', 'पातळ भाजी', 'goan', true, '{"lunch","dinner"}', 15, 20, 'easy', 2, 'steamed-rice', 200, 5, 18, 13, 4, 'A thin, soupy Goan vegetable curry made with leafy greens or mixed vegetables in a light coconut gravy.', 'पातली, सूपी गोवन सब्ज़ी करी — पत्तेदार साग या मिश्रित सब्ज़ियां हल्की नारियल ग्रेवी में।', 'पातळ, रस्सेदार गोवन भाजीची करी — पालेभाज्या किंवा मिश्र भाज्या हलक्या नारळाच्या रश्शात.', 'https://www.youtube.com/results?search_query=patal+bhaji+goan+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('tondak', 'Tondak', 'तोंडक', 'तोंडक', 'goan', false, '{"lunch","dinner"}', 15, 25, 'medium', 2, 'steamed-rice', 340, 22, 10, 24, 2, 'A spicy Goan dry preparation of clams or mussels cooked with a red masala, onions, and coconut — a coastal favourite.', 'लाल मसाला, प्याज़ और नारियल में पकी तीखी गोवन सूखी क्लैम या मसल्स — तटीय पसंदीदा व्यंजन।', 'लाल मसाला, कांदा आणि नारळात शिजवलेल्या तिखट गोवन सुक्या तिसऱ्या किंवा शिंपल्या — किनारपट्टीचा आवडता पदार्थ.', 'https://www.youtube.com/results?search_query=tondak+clams+goan+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('goan-feijoada', 'Goan Feijoada', 'गोवन फीजोआडा', 'गोवन फेजोआदा', 'goan', false, '{"lunch","dinner"}', 30, 75, 'hard', 2, 'steamed-rice', 490, 30, 35, 25, 9, 'A Goan adaptation of the Portuguese bean stew — pork ribs and trotters slow-cooked with red kidney beans and coconut vinegar.', 'पुर्तगाली बीन स्टू का गोवन रूप — पोर्क पसलियां और खुर राजमा के साथ नारियल सिरके में धीमी आंच पर पकाए।', 'पोर्तुगीज बीन स्ट्यूचे गोवन रूपांतर — डुकराच्या फासळ्या आणि खुरे राजम्यासोबत नारळाच्या व्हिनेगरमध्ये मंद आचेवर शिजवलेले.', 'https://www.youtube.com/results?search_query=goan+feijoada+recipe+pork+beans+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('idli', 'Idli', 'इडली', 'इडली', 'tamil', true, '{"breakfast"}', 480, 15, 'medium', 2, NULL, 150, 4.5, 30, 1.5, 1.2, 'Soft steamed rice and lentil cakes served with sambar and coconut chutney, the quintessential South Indian breakfast.', 'नरम भाप में पकी चावल और दाल की टिकिया, सांभर और नारियल चटनी के साथ परोसी जाने वाली दक्षिण भारतीय नाश्ते की शान।', 'सांबार आणि नारळ चटणीसोबत दिली जाणारी मऊ वाफवलेली तांदूळ आणि डाळीची केक, दक्षिण भारतीय नाश्त्याचा राजा.', 'https://www.youtube.com/results?search_query=idli+recipe+soft+idli+batter+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('masala-dosa', 'Masala Dosa', 'मसाला डोसा', 'मसाला डोसा', 'tamil', true, '{"breakfast","lunch","dinner"}', 480, 20, 'medium', 2, NULL, 320, 7, 48, 11, 3.5, 'Crispy golden crepe made from fermented rice and lentil batter, filled with spiced potato masala.', 'खमीर उठे चावल-दाल के घोल से बना कुरकुरा सुनहरा डोसा, मसालेदार आलू भरकर परोसा जाता है।', 'आंबवलेल्या तांदूळ-डाळीच्या पिठापासून बनवलेला कुरकुरीत सोनेरी डोसा, मसालेदार बटाटा भरून दिला जातो.', 'https://www.youtube.com/results?search_query=masala+dosa+recipe+crispy+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('medu-vada', 'Medu Vada', 'मेदू वड़ा', 'मेदू वडा', 'tamil', true, '{"breakfast"}', 240, 20, 'medium', 2, NULL, 280, 10, 28, 14, 4, 'Crispy, golden, doughnut-shaped fritters made from urad dal batter, crunchy outside and fluffy inside.', 'उड़द दाल के घोल से बने कुरकुरे सुनहरे गोल वड़े, बाहर से करारे और अंदर से मुलायम।', 'उडीद डाळीच्या पिठापासून बनवलेले कुरकुरीत सोनेरी गोल वडे, बाहेरून खुसखुशीत आणि आतून मऊ.', 'https://www.youtube.com/results?search_query=medu+vada+recipe+crispy+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('ven-pongal', 'Ven Pongal', 'वेन पोंगल', 'वेन पोंगल', 'tamil', true, '{"breakfast"}', 15, 30, 'easy', 2, NULL, 290, 8, 38, 12, 2.5, 'Comforting savory porridge of rice and moong dal tempered with ghee, black pepper, and cumin.', 'घी, काली मिर्च और जीरे के तड़के वाला चावल-मूंग दाल का सुखदायक नमकीन दलिया।', 'तूप, काळी मिरी आणि जिऱ्याच्या फोडणीचा तांदूळ-मुगडाळीचा आरामदायक खमंग कांजी.', 'https://www.youtube.com/results?search_query=ven+pongal+recipe+Tamil+style+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('upma', 'Upma', 'उपमा', 'उपमा', 'tamil', true, '{"breakfast"}', 10, 15, 'easy', 2, NULL, 240, 5, 34, 9, 2, 'Quick savory semolina porridge tempered with mustard seeds, curry leaves, and vegetables.', 'राई, कड़ी पत्ता और सब्ज़ियों के तड़के वाला जल्दी बनने वाला नमकीन सूजी का उपमा।', 'मोहरी, कढीपत्ता आणि भाज्यांच्या फोडणीचा झटपट तयार होणारा खमंग रव्याचा उपमा.', 'https://www.youtube.com/results?search_query=upma+recipe+South+Indian+style+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('rava-kesari', 'Rava Kesari', 'रवा केसरी', 'रवा केसरी', 'tamil', true, '{"breakfast"}', 5, 15, 'easy', 2, NULL, 350, 4, 50, 16, 0.5, 'Rich saffron-tinted semolina sweet garnished with cashews and raisins, a beloved Tamil Nadu breakfast treat.', 'काजू-किशमिश से सजा केसर रंग का मीठा सूजी का हलवा, तमिलनाडु का पसंदीदा नाश्ते का मिठाई।', 'काजू-मनुक्यांनी सजवलेला केशरी रंगाचा गोड रव्याचा शिरा, तमिळनाडूमधील आवडता नाश्त्याचा गोड पदार्थ.', 'https://www.youtube.com/results?search_query=rava+kesari+recipe+Tamil+style+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('uttapam', 'Uttapam', 'उत्तपम', 'उत्तपम', 'tamil', true, '{"breakfast"}', 480, 15, 'easy', 2, NULL, 250, 6, 38, 8, 2.5, 'Thick, spongy pancake made from dosa batter topped with onions, tomatoes, and chillies.', 'डोसा बैटर से बना मोटा, मुलायम पैनकेक, प्याज़, टमाटर और मिर्च से सजाकर बनाया जाता है।', 'डोसा पिठापासून बनवलेला जाड, मऊ पॅनकेक, कांदा, टोमॅटो आणि मिरचीने सजवून बनवला जातो.', 'https://www.youtube.com/results?search_query=uttapam+recipe+onion+tomato+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('adai', 'Adai', 'अडई', 'अडई', 'tamil', true, '{"breakfast","lunch"}', 240, 20, 'medium', 2, NULL, 270, 10, 36, 9, 5, 'Protein-rich crispy pancake made from a mixed lentil and rice batter, spiced with whole red chillies and curry leaves.', 'मिश्रित दाल और चावल के घोल से बना प्रोटीन भरपूर कुरकुरा चीला, साबुत लाल मिर्च और कड़ी पत्ते का स्वाद।', 'मिश्र डाळ आणि तांदळाच्या पिठापासून बनवलेला प्रथिनयुक्त कुरकुरीत धिरडे, लाल मिरची आणि कढीपत्त्याचा स्वाद.', 'https://www.youtube.com/results?search_query=adai+dosa+recipe+mixed+dal+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
