INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('safed-maas', 'Safed Maas', 'सफ़ेद मांस', 'सफेद मांस', 'rajasthani', false, '{"dinner"}', 20, 55, 'hard', 2, 'naan', 520, 32, 10, 40, 1, 'Rich white mutton curry with cashew-cream gravy, a Rajasthani royal delicacy.', 'काजू-मलाई की ग्रेवी में पका सफ़ेद मटन — राजस्थान का शाही व्यंजन।', 'काजू-मलईच्या ग्रेव्हीतले सफेद मटण — राजस्थानचा शाही पदार्थ.', 'https://www.youtube.com/results?search_query=safed+maas+recipe+rajasthani+white+mutton+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('papad-ki-sabzi', 'Papad ki Sabzi', 'पापड़ की सब्ज़ी', 'पापडाची भाजी', 'rajasthani', true, '{"lunch","dinner"}', 5, 15, 'easy', 2, 'steamed-rice', 220, 8, 18, 14, 2, 'Quick curry made from broken papad pieces in a spiced yogurt gravy, a desert-resourceful dish.', 'दही की मसालेदार ग्रेवी में पापड़ के टुकड़ों से बनी झटपट सब्ज़ी — रेगिस्तानी जुगाड़।', 'दही-मसाल्याच्या ग्रेव्हीत पापडाचे तुकडे शिजवलेली झटपट भाजी — वाळवंटातील कल्पक पदार्थ.', 'https://www.youtube.com/results?search_query=papad+ki+sabzi+recipe+rajasthani+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('bajre-ki-roti', 'Bajre ki Roti', 'बाजरे की रोटी', 'बाजरीची भाकरी', 'rajasthani', true, '{"lunch","dinner"}', 10, 15, 'medium', 2, 'roti', 200, 5, 35, 6, 4, 'Rustic pearl millet flatbread, the daily bread of rural Rajasthan served with ghee and jaggery.', 'बाजरे के आटे की देसी रोटी — राजस्थान के गाँवों की रोज़ की रोटी, घी-गुड़ के साथ।', 'बाजरीच्या पिठाची देशी भाकरी — राजस्थानच्या गावांचा रोजचा पदार्थ, तूप-गुळासोबत.', 'https://www.youtube.com/results?search_query=bajre+ki+roti+recipe+rajasthani+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('besan-gatte', 'Besan Gatte', 'बेसन के गट्टे', 'बेसनाचे गट्टे', 'rajasthani', true, '{"lunch","dinner"}', 15, 20, 'easy', 2, 'steamed-rice', 280, 10, 26, 16, 4, 'Simple steamed gram flour dumplings tossed in a dry spice tempering, a quick Rajasthani side dish.', 'सूखे मसालों में भुने उबले बेसन के गट्टे — राजस्थान का सादा और झटपट व्यंजन।', 'कोरड्या मसाल्यांत परतलेले उकडलेले बेसनाचे गट्टे — राजस्थानचा साधा आणि झटपट पदार्थ.', 'https://www.youtube.com/results?search_query=besan+gatte+dry+recipe+rajasthani+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('mogar-dal', 'Mogar Dal', 'मोगर दाल', 'मोगर डाळ', 'rajasthani', true, '{"lunch","dinner"}', 10, 25, 'easy', 2, 'steamed-rice', 210, 14, 30, 5, 6, 'Simple Rajasthani moong dal tempered with ghee, cumin, and dried red chillies.', 'घी, जीरे और सूखी मिर्च के तड़के वाली सादी राजस्थानी मूँग दाल।', 'तूप, जिरे आणि सुक्या मिरचीच्या फोडणीची साधी राजस्थानी मूग डाळ.', 'https://www.youtube.com/results?search_query=mogar+dal+recipe+rajasthani+moong+dal+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('panchkuta', 'Panchkuta', 'पंचकूटा', 'पंचकूटा', 'rajasthani', true, '{"lunch","dinner"}', 480, 30, 'medium', 2, 'bhakri', 190, 4, 22, 10, 5, 'Five dried desert ingredients — ker, sangri, kumatiya, gunda, and amchur — cooked with spices.', 'रेगिस्तान के पाँच सूखे जंगली फल — केर, सांगरी, कुमटिया, गुंदा, अमचूर — मसालों में पकाए हुए।', 'वाळवंटातील पाच सुक्या रानफळे — केर, सांगरी, कुमटिया, गुंदा, आमचूर — मसाल्यांत शिजवलेले.', 'https://www.youtube.com/results?search_query=panchkuta+recipe+rajasthani+panchmel+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('chakki-ki-sabzi', 'Chakki ki Sabzi', 'चक्की की सब्ज़ी', 'चक्कीची भाजी', 'rajasthani', true, '{"lunch","dinner"}', 10, 20, 'easy', 2, 'roti', 250, 8, 28, 12, 3, 'Wheat flour dumplings cooked in a spiced onion-tomato gravy, a resourceful Rajasthani dish.', 'गेहूँ के आटे की लोइयाँ प्याज़-टमाटर की मसालेदार ग्रेवी में पकी हुई — राजस्थान की जुगाड़ वाली सब्ज़ी।', 'गव्हाच्या पिठाच्या लोया कांदा-टोमॅटोच्या मसालेदार ग्रेव्हीत शिजवलेल्या — राजस्थानची कल्पक भाजी.', 'https://www.youtube.com/results?search_query=chakki+ki+sabzi+recipe+rajasthani+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('raabdi', 'Raabdi', 'राबड़ी', 'राबडी', 'rajasthani', true, '{"breakfast","lunch","dinner"}', 5, 20, 'easy', 2, 'bhakri', 230, 7, 40, 5, 3, 'Thick porridge of bajra or maize flour cooked in buttermilk, a Rajasthani comfort food for all meals.', 'छाछ में पकाई बाजरे या मक्के की गाढ़ी राबड़ी — राजस्थान का देसी सुपरफ़ूड।', 'ताकात शिजवलेले बाजरी किंवा मक्याच्या पिठाचे घट्ट पेय — राजस्थानचे देशी सुपरफूड.', 'https://www.youtube.com/results?search_query=rajasthani+raabdi+recipe+bajra+buttermilk+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('bajra-khichdi', 'Bajra Khichdi', 'बाजरे की खिचड़ी', 'बाजरीची खिचडी', 'rajasthani', true, '{"breakfast","lunch","dinner"}', 15, 30, 'easy', 2, 'roti', 310, 10, 45, 11, 5, 'Hearty pearl millet and moong dal khichdi, a winter staple in rural Rajasthan served with ghee and buttermilk.', 'बाजरा और मूँग दाल की पौष्टिक खिचड़ी — राजस्थान के गाँवों का सर्दियों का खाना, घी-छाछ के साथ।', 'बाजरी आणि मूग डाळीची पौष्टिक खिचडी — राजस्थानच्या गावांचा हिवाळ्यातला पदार्थ, तूप-ताकासोबत.', 'https://www.youtube.com/results?search_query=bajra+khichdi+recipe+rajasthani+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('lehsun-ki-chutney', 'Lehsun ki Chutney', 'लहसुन की चटनी', 'लसणाची चटणी', 'rajasthani', true, '{"lunch","dinner"}', 5, 10, 'easy', 2, 'roti', 60, 1, 5, 4, 1, 'Fiery roasted garlic chutney with dried red chillies, an essential Rajasthani condiment for dal-baati.', 'भुने लहसुन और सूखी लाल मिर्च की तीखी चटनी — दाल-बाटी की अधूरी साथी।', 'भाजलेला लसूण आणि सुक्या लाल मिरचीची तिखट चटणी — दाल-बाटीची अपरिहार्य सोबत.', 'https://www.youtube.com/results?search_query=lehsun+ki+chutney+rajasthani+garlic+chutney+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('bikaneri-bhujia', 'Bikaneri Bhujia', 'बीकानेरी भुजिया', 'बिकानेरी भुजिया', 'rajasthani', true, '{"breakfast","lunch"}', 20, 20, 'hard', 2, 'roti', 350, 10, 35, 20, 4, 'Thin crispy fried gram flour noodles from Bikaner, Rajasthan''s most famous namkeen snack.', 'बेसन की बारीक कुरकुरी तली हुई सेव — बीकानेर का विश्वप्रसिद्ध नमकीन।', 'बेसनाच्या बारीक कुरकुरीत तळलेल्या शेव — बिकानेरचा जगप्रसिद्ध नमकीन.', 'https://www.youtube.com/results?search_query=bikaneri+bhujia+recipe+at+home+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('mohan-maas', 'Mohan Maas', 'मोहन मांस', 'मोहन मांस', 'rajasthani', false, '{"dinner"}', 25, 60, 'hard', 2, 'naan', 550, 34, 12, 42, 1, 'Royal Rajasthani mutton slow-cooked in milk, cream, and cardamom — a Maharaja''s feast dish.', 'दूध, मलाई और इलायची में धीमी आँच पर पका शाही मटन — महाराजाओं का व्यंजन।', 'दूध, मलई आणि वेलचीत मंद आचेवर शिजवलेले शाही मटण — महाराजांचा पदार्थ.', 'https://www.youtube.com/results?search_query=mohan+maas+recipe+rajasthani+royal+mutton+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('jungli-maas', 'Jungli Maas', 'जंगली मांस', 'जंगली मांस', 'rajasthani', false, '{"dinner"}', 10, 50, 'easy', 2, 'roti', 450, 36, 4, 32, 1, 'Rustic hunter-style mutton cooked with just ghee, red chillies, and salt — no onion, no tomato.', 'सिर्फ़ घी, लाल मिर्च और नमक में पका देसी मटन — बिना प्याज़-टमाटर, शिकारी अंदाज़।', 'फक्त तूप, लाल मिरची आणि मीठ घालून शिजवलेले देशी मटण — कांदा-टोमॅटो नाही, शिकारी पद्धत.', 'https://www.youtube.com/results?search_query=jungli+maas+recipe+rajasthani+wild+meat+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;